{"type":"user","message":{"role":"user","content":[{"tool_use_id":"toolu_01CU9whTZPvi3yUybGdiruYQ","type":"tool_result","content":"1	/**
2	 * The settled words of the left diagonals, and the picture they predict.
3	 *
4	 *   node explorer/settledwords.mjs
5	 *
6	 * Diagonal k of the seed's picture, leftDiagonal k j = evolve (j+k) (-j), is
7	 * eventually periodic with a power-of-two period. Its *settled word* S_k is
8	 * the periodic function on all of Z that agrees with the diagonal from its
9	 * onset on, kept in absolute phase (S_k(j) is indexed by the diagonal's own
10	 * j, not by "position in the period"). Rowland 2006 §6 observes that S_k is
11	 * fixed by S_{k-2} and S_{k-1} alone whenever S_{k-1} has a black cell, so
12	 * the settled region is the same for every configuration white far to the
13	 * left, up to one choice at each eventually-white diagonal. This script
14	 *
15	 *   1. reads S_k for k <= K from N rows of the engine, and checks S_k against
16	 *      the unique periodic solution of the diagonal recurrence driven by
17	 *      S_{k-2}, S_{k-1} (or, at a white diagonal, against the two solutions);
18	 *   2. lists the eventually-white diagonals and the branch taken there;
19	 *   3. evaluates the settled picture at the centre, s(t) = S_t(0), and at
20	 *      column -1, S_{t-1}(1), against the real centre column and column -1,
21	 *      i.e. measures the deviation E = picture xor S on the seam;
22	 *   4. looks for a repeated consecutive pair (S_{k-1}, S_k), which would make
23	 *      the settled words, and s, periodic in k from there on.
24	 *
25	 * Nothing here is a proof. See explorer/README.md.
26	 */
27	
28	import { centerBitIndex, rows } from './rule30.mjs';
29	
30	const N = 6000;
31	const K = 2400;
32	const MIN_CYCLES = 8;
33	const MAX_P = 64;
34	const MIN_TAIL = 128;   // a short constant tail is chance, not a period 1
35	
36	/** Diagonals D_k(j) = cell (j+k, -j) of the seed, k <= K, from N engine rows. */
37	export function seedDiagonals(N, K) {
38	  const diag = [];
39	  for (let k = 0; k <= K; k++) diag.push(new Uint8Array(N - k));
40	  const base = centerBitIndex(N);
41	  let t = 0;
42	  for (const row of rows(N)) {
43	    const s = row.toString(2);
44	    const len = s.length;
45	    for (let k = 0; k <= K && k <= t; k++) {
46	      const pos = base - (t - k);
47	      diag[k][t - k] = pos < len && s.charCodeAt(len - 1 - pos) === 49 ? 1 : 0;
48	    }
49	    t++;
50	  }
51	  return diag;
52	}
53	
54	/**
55	 * Diagonals of the half-line x <= -1 grown from the left word w (w[0] = cell -1)
56	 * with boundary c (a function of t), for N rows: D_k(j) = cell (j+k, -j), with
57	 * D_k(0) = c(k). Same coordinates as seedDiagonals when c is the centre column
58	 * and w is empty.
59	 */
60	export function halfLineDiagonals(c, w, N, K) {
61	  const diag = [];
62	  for (let k = 0; k <= K; k++) diag.push(new Uint8Array(N - k));
63	  const W = N + w.length + 3;
64	  let row = new Uint8Array(W), next = new Uint8Array(W);
65	  for (let i = 0; i < w.length; i++) row[i + 1] = w[i];
66	  for (let t = 0; t < N; t++) {
67	    row[0] = c(t);
68	    for (let k = 0; k <= K && k <= t; k++) diag[k][t - k] = row[t - k];
69	    const lim = Math.min(W - 2, t + w.length + 2);
70	    for (let j = 1; j <= lim; j++) next[j] = row[j + 1] ^ (row[j] | row[j - 1]);
71	    for (let j = lim + 1; j < W; j++) next[j] = 0;
72	    [row, next] = [next, row];
73	  }
74	  return diag;
75	}
76	
77	const mod = (a, p) => ((a % p) + p) % p;
78	
79	/**
80	 * Settle a diagonal: minimal power-of-two period p with at least MIN_CYCLES
81	 * cycles and MIN_TAIL cells of tail, its onset, and the settled word in
82	 * absolute phase, word[j mod p] = S(j).
83	 */
84	export function settle(a, minCycles = MIN_CYCLES, maxP = MAX_P) {
85	  for (let p = 1; p <= maxP && p * minCycles <= a.length; p *= 2) {
86	    let lastBreak = -1;
87	    for (let i = p; i < a.length; i++) if (a[i] !== a[i - p]) lastBreak = i;
88	    const onset = lastBreak < 0 ? 0 : lastBreak - p + 1;
89	    if (a.length - onset >= Math.max(minCycles * p, MIN_TAIL)) {
90	      const word = new Uint8Array(p);
91	      for (let r = 0; r < p; r++) word[r] = a[onset + mod(r - onset, p)];
92	      return { p, onset, word };
93	    }
94	  }
95	  return null;
96	}
97	
98	export const at = (S, j) => S.word[mod(j, S.p)];
99	export const key = (S) => `${S.p}:${Array.from(S.word).join('')}`;
100	export const isWhite = (S) => S.word.every((v) => v === 0);
101	
102	/**
103	 * F(Sa, Sb): the periodic solutions x of x(i+1) = Sa(i+2) xor (Sb(i+1) || x(i)).
104	 * If Sb has a black cell the solution with period q = max(pa, pb) is unique
105	 * and is returned as [x]. If Sb is white the machine is x(i+1) = Sa(i+2) xor x(i)
106	 * and the two solutions (complements of each other, period q or 2q) are returned.
107	 */
108	export function F(Sa, Sb) {
109	  const q = Math.max(Sa.p, Sb.p);
110	  if (!isWhite(Sb)) {
111	    let i0 = -1;
112	    for (let i = 0; i < q; i++) if (at(Sb, i + 1) === 1) { i0 = i; break; }
113	    const x = new Uint8Array(2 * q + 2);      // x[m] = value at index i0 + 1 + m
114	    x[0] = 1 ^ at(Sa, i0 + 2);
115	    for (let m = 0; m < 2 * q + 1; m++) {
116	      const i = i0 + 1 + m;
117	      x[m + 1] = at(Sa, i + 2) ^ (at(Sb, i + 1) | x[m]);
118	    }
119	    for (let m = 0; m < q; m++) if (x[m] !== x[m + q]) throw new Error('F: not q-periodic');
120	    const word = new Uint8Array(q);
121	    for (let m = 0; m < q; m++) word[mod(i0 + 1 + m, q)] = x[m];
122	    return [{ p: q, onset: 0, word }];
123	  }
124	  const sols = [];
125	  for (const x0 of [0, 1]) {
126	    const x = new Uint8Array(2 * q + 1);
127	    x[0] = x0;
128	    for (let i = 0; i < 2 * q; i++) x[i + 1] = at(Sa, i + 2) ^ x[i];
129	    const p = x[q] === x[0] ? q : 2 * q;
130	    sols.push({ p, onset: 0, word: x.slice(0, p) });
131	  }
132	  return sols;
133	}
